This is what I came up with as far as a patch for adding support in this platform. It may be the wrong place, but it's something. I can put this into a pull request at this point. Comments would be appreciated:

```
diff --git a/providers/implementations/rands/seeding/rand_cpu_x86.c b/providers/implementations/rands/seeding/rand_cpu_x86.c
index fd47de9ad0..9097d1d8e7 100644
--- a/providers/implementations/rands/seeding/rand_cpu_x86.c
+++ b/providers/implementations/rands/seeding/rand_cpu_x86.c
@@ -13,8 +13,13 @@
 #include "prov/seeding.h"

 #ifdef OPENSSL_RAND_SEED_RDCPU
+# if defined(OPENSSL_SYSNAME_TANDEM) && defined(_TNS_X_TARGET)
+#  include <builtin.h> /* _rdrand64 */
+#  include <string.h> /* memcpy */
+# else
 size_t OPENSSL_ia32_rdseed_bytes(unsigned char *buf, size_t len);
 size_t OPENSSL_ia32_rdrand_bytes(unsigned char *buf, size_t len);
+#endif

 /*
  * Acquire entropy using Intel-specific cpu instructions
@@ -35,9 +40,36 @@ size_t prov_acquire_entropy_from_cpu(RAND_POOL *pool)

     bytes_needed = rand_pool_bytes_needed(pool, 1 /*entropy_factor*/);
     if (bytes_needed > 0) {
+
         buffer = rand_pool_add_begin(pool, bytes_needed);

         if (buffer != NULL) {
+#if defined(OPENSSL_SYSNAME_TANDEM) && defined(_TNS_X_TARGET)
+            size_t bytes_remaining = bytes_needed;
+            while (bytes_remaining > 0) {
+                /* Always use 64 bit fetch, then use the lower bytes as needed. */
+                /* The platform is big-endian. */
+                unsigned long long random_value = 0;
+                if (_rdrand64(&random_value) != 0) {
+                    unsigned char *random_buffer = (unsigned char *)&random_value;
+                    if (bytes_remaining > sizeof(random_value)) {
+                        memcpy(buffer, random_buffer, sizeof(random_value));
+                        bytes_remaining -= sizeof(random_value);
+                    } else {
+                        memcpy(buffer,
+                            random_buffer + (sizeof(random_value) - bytes_remaining),
+                            bytes_remaining);
+                        bytes_remaining = 0;
+                    }
+                } else
+                    break;
+            }
+            if (bytes_remaining == 0) {
+                rand_pool_add_end(pool, bytes_needed, 8 * bytes_needed);
+            } else {
+                rand_pool_add_end(pool, 0, 0);
+            }
+#else
             /* Whichever comes first, use RDSEED, RDRAND or nothing */
             if ((OPENSSL_ia32cap_P[2] & (1 << 18)) != 0) {
                 if (OPENSSL_ia32_rdseed_bytes(buffer, bytes_needed)
@@ -52,6 +84,7 @@ size_t prov_acquire_entropy_from_cpu(RAND_POOL *pool)
             } else {
                 rand_pool_add_end(pool, 0, 0);
             }
+#endif
         }
     }
```
